using System.Text.RegularExpressions;

namespace Lockflight.Cli.Review;

/// <summary>
/// Whether a migration designer file or a model snapshot looks like the code EF Core generates for it, so its diff can be listed
/// instead of shown. The file must start with the <c>// &lt;auto-generated /&gt;</c> header and, with comments, preprocessor lines and
/// the contents of string literals blanked (<see cref="CSharpMask"/>), hold only: usings, a namespace, the
/// <c>[DbContext(typeof(…))]</c> and <c>[Migration("…")]</c> attributes, one partial class (deriving from <c>ModelSnapshot</c> for a
/// snapshot) with one <c>BuildTargetModel</c> (designer) or <c>BuildModel</c> (snapshot) override, and model-builder statements:
/// calls on <c>modelBuilder</c>, a builder lambda's parameter (<c>b</c>, <c>b1</c>…, <c>t</c>, <c>j</c>) or the providers'
/// builder extension classes, chained calls whose names EF's fluent API uses (<c>Has…</c>, <c>Is…</c>, <c>With…</c>…), the enum
/// values EF writes, and seed rows of literal values. Anything else (another member, a call on any other type, a lambda with
/// another parameter, a statement) makes the file look hand-written, and it is shown in full. It is a light check of the shape,
/// not a parser: a file that passes holds no code beyond model-building calls with literal arguments.
/// </summary>
internal static partial class EfGeneratedCode
{
    private const string Header = "// <auto-generated />";
    private const string DesignerMethod = "BuildTargetModel";
    private const string SnapshotMethod = "BuildModel";

    public static bool IsMigrationDesigner(string content) => HasShape(content, DesignerMethod, snapshot: false);

    public static bool IsModelSnapshot(string content) => HasShape(content, SnapshotMethod, snapshot: true);

    private static bool HasShape(string content, string method, bool snapshot)
    {
        string[] lines = content.TrimStart('﻿').Split('\n');
        if (lines[0].Trim() != Header)
        {
            return false;
        }

        int classes = 0;
        int methods = 0;
        foreach (string line in CSharpMask.Mask(content.TrimStart('﻿')).Split('\n').Select(line => line.Trim()))
        {
            if (ClassLine().Match(line) is { Success: true } declaration)
            {
                classes++;
                if (declaration.Groups["snapshot"].Success != snapshot)
                {
                    return false;
                }
            }
            else if (MethodLine().Match(line) is { Success: true } build)
            {
                methods++;
                if (build.Groups["name"].Value != method)
                {
                    return false;
                }
            }
            else if (!IsAllowedLine(line))
            {
                return false;
            }
        }

        return classes == 1 && methods == 1;
    }

    private static bool IsAllowedLine(string line) =>
        line.Length == 0
        || (!line.Contains('$', StringComparison.Ordinal) && IsAllowedCode(line));

    private static bool IsAllowedCode(string line) =>
        UsingLine().IsMatch(line)
        || NamespaceLine().IsMatch(line)
        || PunctuationLine().IsMatch(line)
        || AttributeLine().IsMatch(line)
        || line == "new"
        || BuilderName().IsMatch(line)
        || SeedLine().IsMatch(line)
        || (BuilderLine().IsMatch(line) && HasOnlyBuilderCode(line));

    /// <summary>
    /// Whether every name in a builder line is a fluent call (after a dot), a builder, an EF enum or extension class before a dot,
    /// <c>typeof</c> or a value type's constructor before a parenthesis, or a keyword; a fluent call's generic arguments are set aside.
    /// </summary>
    private static bool HasOnlyBuilderCode(string line)
    {
        string code = GenericArguments().Replace(line, string.Empty);
        foreach (Match call in ChainedCall().Matches(code))
        {
            if (!FluentName().IsMatch(call.Groups["name"].Value))
            {
                return false;
            }
        }

        foreach (Match name in LeadingName().Matches(code))
        {
            string value = name.Groups["name"].Value;
            bool allowed = name.Groups["next"].Value switch
            {
                "." => BuilderName().IsMatch(value) || ReceiverName().IsMatch(value),
                "(" => value == "typeof" || (name.Groups["new"].Success && ValueType().IsMatch(value)),
                _ => BuilderName().IsMatch(value) || Keyword().IsMatch(value) || (name.Groups["new"].Success && ValueType().IsMatch(value)),
            };
            if (!allowed)
            {
                return false;
            }
        }

        return true;
    }

    [GeneratedRegex(@"^(?:(?:public|internal|sealed)\s+)*partial\s+class\s+\w+(?<snapshot>\s*:\s*ModelSnapshot)?$")]
    private static partial Regex ClassLine();

    [GeneratedRegex(@"^protected\s+override\s+void\s+(?<name>\w+)\s*\(\s*ModelBuilder\s+modelBuilder\s*\)$")]
    private static partial Regex MethodLine();

    [GeneratedRegex(@"^using\s+[\w.]+\s*;$")]
    private static partial Regex UsingLine();

    [GeneratedRegex(@"^namespace\s+[\w.]+\s*;?$")]
    private static partial Regex NamespaceLine();

    [GeneratedRegex(@"^[{}();,\s]+$")]
    private static partial Regex PunctuationLine();

    [GeneratedRegex(@"^\[\s*(?:DbContext\s*\(\s*typeof\s*\(\s*[\w.]+\s*\)\s*\)|Migration\s*\(\s*""[^""]*""\s*\))\s*\]$")]
    private static partial Regex AttributeLine();

    /// <summary>A property of a seed row: a name and a literal (number, string, character, bool, null) or a value type's constructor of literals.</summary>
    [GeneratedRegex(@"^\w+\s*=\s*(?:-?\d[\w.]*|@?""[^""]*""|'[^']*'|true|false|null|new\s+(?:DateTime|DateTimeOffset|DateOnly|TimeOnly|TimeSpan|Guid)\s*\([^()]*\))\s*,?$")]
    private static partial Regex SeedLine();

    [GeneratedRegex(@"^(?:\.|[A-Za-z_]\w*\s*\.)")]
    private static partial Regex BuilderLine();

    /// <summary>A fluent call's generic arguments: type names right after a dotted method name and before its parenthesis.</summary>
    [GeneratedRegex(@"(?<=\.\s*[A-Za-z_]\w*)\s*<[\w\s,.?\[\]]*>(?=\s*\()")]
    private static partial Regex GenericArguments();

    [GeneratedRegex(@"\.\s*(?<name>[A-Za-z_]\w*)\s*\(")]
    private static partial Regex ChainedCall();

    /// <summary>A name not after a dot (nor inside another name or a number), with what follows it.</summary>
    [GeneratedRegex(@"(?<new>\bnew\s+)?(?<![\w.])(?<name>[A-Za-z_]\w*)\s*(?<next>[.(]?)")]
    private static partial Regex LeadingName();

    [GeneratedRegex(@"^(?:modelBuilder|b\d*|t|j)$")]
    private static partial Regex BuilderName();

    [GeneratedRegex(@"^(?:Has|Is|With|On|To|Use|Uses|Value|Property|Properties|Entity|Owns|Navigation|Complex|Starts|Increments|Include|Exclude|Ignore|Split)\w*$")]
    private static partial Regex FluentName();

    [GeneratedRegex(@"^(?:(?:SqlServer|Npgsql|MySql|Sqlite|Oracle|Relational|Cosmos)(?:Model|Property|Entity|EntityType|Index|Key|ComplexType)BuilderExtensions|DeleteBehavior|DateTimeKind|PropertyAccessMode|ChangeTrackingStrategy|(?:SqlServer|Npgsql|MySql|Oracle)ValueGenerationStrategy)$")]
    private static partial Regex ReceiverName();

    [GeneratedRegex(@"^(?:DateTime|DateTimeOffset|DateOnly|TimeOnly|TimeSpan|Guid)$")]
    private static partial Regex ValueType();

    [GeneratedRegex(@"^(?:new|null|true|false|string|int|long|short|byte|bool|decimal|double|float|char|object)$")]
    private static partial Regex Keyword();
}
